import React from "react";
import {
  StyleSheet,
  View,
  NativeModules,
  Image,
  Pressable,
  Text,
} from "react-native";
import { GlobalStyle } from "../../../../assets/GlobalStyle";
import Ionicon from "react-native-vector-icons/Ionicons";
import { CAPTURE_SIZE } from "./CaptureButton";
import { styles as storyStyles } from "../style";
import { Campus } from "../../../../assets/Campus";
import { createAnimatableComponent } from "react-native-animatable";
import { analytics } from "../../../../assets/Analytics";

const AnimPressable = createAnimatableComponent(Pressable);

export class CameraRoll extends React.Component {
  constructor() {
    super();
    this.pressable = React.createRef();
    this.state = {
      open: false,
      photos: [],
    };
  }
  onPress = () => {
    analytics.breadcrumb("Opened camera library for stories");
    Campus.Funcs.images
      .selectFromLibrary({})
      .then((res) => {
        if (!res.didCancel) this.props.onImageSelected(res);
      })
      .catch((err) => console.warn(err));
  };

  componentDidUpdate(prevProps) {
    const {
      recording: prevRecording,
      maxGraphicsReached: prevMaxGraphicsReached,
    } = prevProps;
    const { recording, maxGraphicsReached } = this.props;

    if (this.pressable.current) {
      const pressable = this.pressable.current;
      const duration = 500;
      if (
        (recording && !prevRecording) ||
        (maxGraphicsReached && !prevMaxGraphicsReached)
      )
        pressable.fadeOut(duration);
      else if (
        (!recording && prevRecording) ||
        (!maxGraphicsReached && prevMaxGraphicsReached)
      )
        pressable.fadeIn(duration);
    }
  }

  render() {
    return (
      <AnimPressable
        ref={this.pressable}
        hitSlop={8}
        style={[storyStyles.iconShadow, styles.container]}
        onTouchStart={this.onPress}
      >
        <Ionicon name={"images-outline"} size={SIZE} color={"#ffffff"} />
      </AnimPressable>
    );
  }
}

const SIZE = GlobalStyle.Measurements.width * 0.075;
const styles = StyleSheet.create({
  container: {
    position: "absolute",

    marginTop: GlobalStyle.Measurements.height * 0.95 - CAPTURE_SIZE + SIZE / 2,
    marginLeft: GlobalStyle.Measurements.width / 6 - SIZE / 2,

    alignSelf: "flex-start",
  },
});
