import React from "react";
import { Platform } from "react-native";
import { PanResponder } from "react-native";
import { Alert } from "react-native";
import { Pressable } from "react-native";
import { Animated } from "react-native";
import { View, Text } from "react-native";
import { RNCamera } from "react-native-camera";
import { analytics } from "../../../assets/Analytics";
import { GlobalStyle } from "../../../assets/GlobalStyle";
import { CameraRoll } from "./components/CameraRoll";
import { CaptureButton, MAX_VIDEO_DURATION } from "./components/CaptureButton";
import { FlashButton } from "./components/FlashButton";
import { FlipCamera } from "./components/FlipCamera";
import { GraphicFocus } from "./components/GraphicFocus";
import { Graphics } from "./components/Graphics";
import { StoryHeader } from "./components/Header";
import { styles } from "./style";

const AnimatedCamera = Animated.createAnimatedComponent(RNCamera);

const MAX_ZOOM = Platform.OS == "ios" ? 8 : 1;
export const MAX_NUMBER_GRAPHICS = 8;
const CAMERA_TYPES = ["back", "front"];

export class StoryCamera extends React.Component {
  // TODO: https://github.com/Jobeso/react-native-story-share

  constructor() {
    super();
    this.camera = React.createRef();

    this.state = {
      cameraZoom: new Animated.Value(0),
      graphics: [], // The images or videos taken by the camera
      flash: "auto",
      cameraType: "back",
    };
  }

  render() {
    const maxGraphicsReached =
      this.state.graphics.length >= MAX_NUMBER_GRAPHICS;

    return (
      <AnimatedCamera
        ref={this.camera}
        autoFocus={RNCamera.Constants.AutoFocus.on}
        flashMode={this.props.showingPreview ? "off" : this.state.flash}
        defaultVideoQuality={RNCamera.Constants.VideoQuality["1080p"]}
        style={styles.camera}
        zoom={this.state.cameraZoom}
        maxZoom={MAX_ZOOM}
        type={this.state.cameraType}
        useNativeZoom={true}
        onDoubleTap={this.flipCamera}
      >
        {({ camera, status, recordAudioPermissionStatus }) => (
          <React.Fragment>
            <StoryHeader goBack={this.props.navigation.goBack} />
            <CaptureButton
              takePicture={() => this.takePicture(camera)}
              startRecording={() => this.startRecording(camera)}
              restartRecording={() => this.restartRecording(camera)}
              stopRecording={() => this.stopRecording(camera)}
              colors={this.props.store.app.campus.colors}
              maxGraphicsReached={maxGraphicsReached}
            />
            <FlashButton
              onPress={this.toggleFlash}
              flash={this.state.flash}
              recording={this.state.recording}
              maxGraphicsReached={maxGraphicsReached}
            />
            {this.state.graphics.length > 0 && (
              <Graphics
                graphics={this.state.graphics}
                maxNumber={MAX_NUMBER_GRAPHICS}
                onGraphicPress={this.onGraphicPress}
                onGraphicDeleted={this.onGraphicDeleted}
                showPreview={this.props.showPreview}
                campusColors={this.props.store.app.campus.colors}
              />
            )}
            <FlipCamera
              onPress={this.flipCamera}
              maxGraphicsReached={maxGraphicsReached}
            />
            <CameraRoll
              onImageSelected={this.onImageSelected}
              recording={this.state.recording}
              maxGraphicsReached={maxGraphicsReached}
            />

            {this.state.focus && (
              <GraphicFocus
                focus={this.state.focus}
                onClose={() => this.setState({ focus: false })}
              />
            )}
          </React.Fragment>
        )}
      </AnimatedCamera>
    );
  }
  flipCamera = () => {
    const cameraType =
      CAMERA_TYPES[1 - CAMERA_TYPES.indexOf(this.state.cameraType)];
    analytics.breadcrumb(`Flipped stories camera to '${cameraType}'`);
    this.setState({ cameraType });
  };
  zoomCamera = (zoom = false) => {
    const cameraZoom = this.state.cameraZoom._value;
    var newValue = 0;

    if (zoom === false) {
      if (cameraZoom > 1) newValue = 1;
      else if (cameraZoom > 0 && cameraZoom <= 1) newValue = 0;
      else if (cameraZoom == 0) newValue = 1;
      else newValue = 1;
    } else if (typeof zoom == "number") newValue = zoom;

    newValue = newValue / MAX_ZOOM;
    this.state.cameraZoom.setValue(newValue);
  };
  toggleFlash = () => {
    const { flash: prevFlash } = this.state;
    var toFlash;

    if (prevFlash == "auto") toFlash = "off";
    else if (prevFlash == "on") toFlash = "off";
    else toFlash = "on";

    analytics.breadcrumb(`Changed stories camera flash to '${toFlash}'`);
    this.setState({ flash: toFlash });
  };
  takePicture = async (camera) => {
    analytics.breadcrumb("Took stories picture");
    const options = { quality: 0.5, base64: true };
    const data = await camera.takePictureAsync(options);
    this.appendGraphics({ uri: data.uri, type: "image" });
  };
  startRecording = async (camera) => {
    analytics.breadcrumb("Started stories recording");
    this.setState({ recording: true });

    // Handle the flash, by turning it on
    const { flash } = this.state;
    if (flash == "on" || flash == "auto") {
      // Save the previous flash state to reset it after recording
      this.setState({ flash: "torch", prevFlashState: flash });
    }

    const options = {
      quality: RNCamera.Constants.VideoQuality["1080p"],
      orientation: "portrait",
    };
    const data = await camera.recordAsync(options);
    this.appendGraphics({ uri: data.uri, type: "video" });
  };
  restartRecording = (camera) => {
    analytics.breadcrumb("Restarted stories recording");
    camera.stopRecording();
  };
  stopRecording = async (camera) => {
    if (this.state.recording) {
      analytics.breadcrumb("Stopped stories recording");
      this.setState({ recording: false });
      camera.stopRecording();
      this.setState({ flash: this.state.prevFlashState });
    }
  };
  onImageSelected = (response) => {
    analytics.breadcrumb("Selected stories image from camera library");
    const type = response.type.split("/")[0];
    this.appendGraphics({ uri: response.uri, type: type });
  };
  onGraphicPress = async (nativeEvent, graphic) => {
    analytics.breadcrumb("Pressed on stories graphic");
    const { pageX, pageY } = nativeEvent;
    this.setState({ focus: { pageX, pageY, graphic } });
  };
  onGraphicDeleted = (index) => {
    analytics.breadcrumb(`Deleted stories graphic, index: '${index}'`);
    const graphics = this.state.graphics.filter((e, i) => i !== index);
    this.setState({ graphics });
    this.props.onGraphicsChange(graphics);
  };
  appendGraphics = ({ uri, type }) => {
    analytics.breadcrumb(`Appending '${type}' to stories graphics`);
    const graphics = this.state.graphics.concat({ uri, type });

    if (graphics.length <= MAX_NUMBER_GRAPHICS) {
      this.setState({ graphics });
      this.props.onGraphicsChange(graphics);
    } else
      Alert.alert(
        "Max quantity",
        `You can only take ${MAX_NUMBER_GRAPHICS} images/videos`
      );
  };
}
