import React from "react";
import { Pressable, TouchableOpacity, PanResponder, Text } from "react-native";
import { StyleSheet, ScrollView, View } from "react-native";
import StaticSafeAreaInsets from "react-native-static-safe-area-insets";
import { GlobalStyle } from "../../../../assets/GlobalStyle";
import RNVideo from "react-native-video";
import * as Animatable from "react-native-animatable";
import { Animated } from "react-native";
import FontAwesome5 from "react-native-vector-icons/FontAwesome5";
import PropTypes from "prop-types";

export function Graphics(props) {
  return (
    <View style={[styles.outerContainer, props.containerStyle]}>
      <ScrollView
        style={styles.container}
        contentContainerStyle={styles.contentContainer}
        horizontal
        showsHorizontalScrollIndicator={false}
      >
        <View
          style={[
            styles.mapContainer,
            typeof props.sizeScale == "number" && {
              height: GRAPHIC_HEIGHT * props.sizeScale,
            },
          ]}
        >
          {props.graphics.map((elem, index) => (
            <GraphicView
              elem={elem}
              index={index}
              onPress={props.onGraphicPress}
              onDelete={props.onGraphicDeleted}
              selected={index === props.selectedIndex}
              campusColors={props.campusColors}
              sizeScale={props.sizeScale}
            />
          ))}
        </View>
      </ScrollView>
      {props.graphics.length > 0 && props.showFooter && (
        <View style={styles.row}>
          <Text style={styles.text}>
            {props.graphics.length}/{props.maxNumber}
          </Text>
          <TouchableOpacity
            onPress={props.showPreview}
            style={[
              styles.uploadButton,
              { backgroundColor: props.campusColors.main },
            ]}
          >
            <Text style={styles.uploadButtonText}>Upload</Text>
            <FontAwesome5 name={"arrow-right"} color={"#fff"} />
          </TouchableOpacity>
        </View>
      )}
    </View>
  );
}

function GraphicView(props) {
  const marginTop = React.useRef(new Animated.Value(0)).current;
  const animView = React.useRef();

  return (
    <Animatable.View
      ref={animView}
      style={{ marginTop: marginTop }}
      useNativeDriver={false}
      animation={"fadeInRight"}
      key={`graphic_view_stories_${props.index}`}
    >
      <Pressable
        style={[
          styles.graphicView,
          props.selected && {
            borderColor: props.campusColors.light,
            borderWidth: 3,
          },
          typeof props.sizeScale == "number" && {
            width: GRAPHIC_WIDTH * props.sizeScale,
            height: GRAPHIC_HEIGHT * props.sizeScale,
          },
        ]}
        onPress={() => props.onPress({ ...props.elem, index: props.index })}
      >
        {props.elem.type == "image" ? (
          <GlobalStyle.UI.Image
            source={{ uri: props.elem.uri }}
            style={[
              styles.image,
              typeof props.sizeScale == "number" && {
                width: GRAPHIC_WIDTH * props.sizeScale,
                height: GRAPHIC_HEIGHT * props.sizeScale,
              },
            ]}
          />
        ) : (
          <RNVideo
            style={[
              styles.image,
              typeof props.sizeScale == "number" && {
                width: GRAPHIC_WIDTH * props.sizeScale,
                height: GRAPHIC_HEIGHT * props.sizeScale,
              },
            ]}
            source={{ uri: props.elem.uri }}
            muted={true}
            resizeMode={"cover"}
            repeat={true}
          />
        )}
      </Pressable>
      <TouchableOpacity
        style={styles.removeButton}
        onPress={() => props.onDelete(props.index)}
      >
        <FontAwesome5
          size={REMOVE_BUTTON_SIZE / 1.65}
          name={"times"}
          color={"#aaa"}
        />
      </TouchableOpacity>
    </Animatable.View>
  );
}

const GRAPHIC_WIDTH = GlobalStyle.Measurements.width * 0.12;
const GRAPHIC_HEIGHT = GRAPHIC_WIDTH * (14 / 9);
const BORDER_WIDTH = GRAPHIC_WIDTH / 40;
const BORDER_RADIUS = GRAPHIC_WIDTH / 8;
const REMOVE_BUTTON_SIZE = GlobalStyle.Measurements.unit * 0.9;

const styles = StyleSheet.create({
  outerContainer: {
    position: "absolute",
    width: GlobalStyle.Measurements.width,
    top: StaticSafeAreaInsets.safeAreaInsetsTop * 2,
  },
  container: {
    width: GlobalStyle.Measurements.width,
    paddingHorizontal: GlobalStyle.Measurements.width * 0.05,
    padding: 10,
  },
  contentContainer: {
    flexDirection: "column",
  },
  mapContainer: {
    paddingRight: GRAPHIC_WIDTH / 2,
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-start",
    height: GRAPHIC_HEIGHT,
  },

  ///// GRAPHIC VIEW //////
  graphicView: {
    width: GRAPHIC_WIDTH,
    height: GRAPHIC_HEIGHT,
    borderRadius: BORDER_RADIUS,
    borderColor: "#fff",
    borderWidth: BORDER_WIDTH,

    marginRight: GlobalStyle.Measurements.marginHalf,

    overflow: "hidden",
  },

  image: {
    width: GRAPHIC_WIDTH - BORDER_WIDTH * 2,
    height: GRAPHIC_HEIGHT - BORDER_WIDTH * 2,
    // borderRadius: BORDER_RADIUS,

    overflow: "hidden",
  },
  text: {
    ...GlobalStyle.TextStyle.bodySmall,
    color: "#fff",
  },
  removeButton: {
    position: "absolute",
    backgroundColor: "#fff",
    alignItems: "center",
    justifyContent: "center",

    width: REMOVE_BUTTON_SIZE,
    height: REMOVE_BUTTON_SIZE,

    marginLeft: -(REMOVE_BUTTON_SIZE / 3),
    marginTop: -(REMOVE_BUTTON_SIZE / 3),

    borderRadius: REMOVE_BUTTON_SIZE / 2,

    shadowColor: "#000",
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 4,
    elevation: 2,
  },
  row: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "flex-start",

    marginTop: GlobalStyle.Measurements.marginHalf,
    marginLeft: GlobalStyle.Measurements.margin,
  },

  uploadButton: {
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",

    paddingVertical: GlobalStyle.Measurements.marginQuarter,
    paddingHorizontal: GlobalStyle.Measurements.marginHalf,
    marginLeft: GlobalStyle.Measurements.margin,
    borderRadius: 100,

    backgroundColor: GlobalStyle.ColorStyle.getCampusColors().main,
  },
  uploadButtonText: {
    ...GlobalStyle.TextStyle.buttonSmall,
    color: "#fff",
    marginRight: 8,
  },
});

Graphics.defaultProps = {
  showFooter: true,
  selectedIndex: false,
};
Graphics.propTypes = {
  showFooter: PropTypes.bool,
  selectedIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.bool]),
  containerStyle: PropTypes.object,
};
