import React from "react";
import { StyleSheet } from "react-native";
import { Image, View, PanResponder, Animated } from "react-native";
import StaticSafeAreaInsets from "react-native-static-safe-area-insets";
import { analytics } from "../../../assets/Analytics";
import { EventSocietySearch } from "../../../assets/EventSocietySearch";
import { GlobalStyle } from "../../../assets/GlobalStyle";
import { PreviewFooter } from "./components/PreviewFooter";
import { PreviewGraphics } from "./components/PreviewGraphics";
import { PreviewHeader } from "./components/PreviewHeader";
import { ConfirmationPanel } from "../../../assets/ConfirmationPanel";
import { Campus } from "../../../assets/Campus";

export class StoryPreview extends React.Component {
  /**
   * Preview the graphics that a user has taken
   */
  constructor() {
    super();
    this.state = {
      animTop: new Animated.Value(ANIMTOP.HIDE),

      settings: {
        muted: __DEV__, // Have audio in the story
        repeat: true, // Repeat the story indefinitely
      },
    };
  }

  componentDidUpdate(prevProps) {
    const { isActive: prevIsActive } = prevProps;
    const { isActive } = this.props;

    if (isActive && !prevIsActive) this.animate(true);
    else if (!isActive && prevIsActive) this.animate(false);
  }

  animate = (show = false) => {
    var toValue;
    if (show) toValue = ANIMTOP.SHOW;
    else toValue = ANIMTOP.HIDE;

    Animated.spring(this.state.animTop, {
      toValue,
      tension: 30,
      friction: 7,
      useNativeDriver: false,
      restDisplacementThreshold: 10,
      restSpeedThreshold: 10,
    }).start();
  };

  render() {
    const graphics = this.props.graphics || [];
    return (
      <React.Fragment>
        <Animated.View style={[styles.container, { top: this.state.animTop }]}>
          {this.props.isActive && graphics.length > 0 && (
            <PreviewGraphics
              graphics={graphics}
              settings={this.state.settings}
              campusColors={this.props.store.app.campus.colors}
              onGraphicDeleted={this.props.onGraphicDeleted}
            />
          )}
          <PreviewHeader
            close={this.props.onClose}
            selectCampusObject={this.selectCampusObject}
            settings={this.state.settings}
            updateSettings={this.updateSettings}
          />
          <PreviewFooter
            campusColors={this.props.store.app.campus.colors}
            parentHeight={
              styles.container.height - styles.container.paddingBottom
            }
            societyName={this.props.store.society.manageSocietyFocus.name}
            upload={this.upload}
          />
        </Animated.View>
        <ConfirmationPanel
          isActive={this.state.uploaded || this.state.uploading}
          loading={this.state.uploading}
          error={this.state.uploadError}
          successText={"Posted your stories"}
          errorText={"Error posting your stories"}
          loadingText={"Posting your stories"}
          onClose={this.closeConfirmation}
          colors={this.props.store.app.campus.colors}
          onPress={this.closeConfirmation}
        />
        <EventSocietySearch
          isActive={this.state.searchCampusObject}
          onClose={() => this.setState({ searchCampusObject: false })}
          store={this.props.store}
          navigation={this.props.navigation}
          onSelect={console.log}
          preload={false}
        />
      </React.Fragment>
    );
  }
  closeConfirmation = () => {
    if (this.state.uploaded) this.props.navigation.goBack();
    this.setState({
      uploading: false,
      uploadError: false,
    });
  };

  updateSettings = (key, value) => {
    analytics.breadcrumb(`Updating stories preview settings ${key} = ${value}`);
    const { settings } = this.state;
    if (key) settings[key] = value;
    this.setState({ settings });
  };
  selectCampusObject = () => {
    /** Select an event or news from campus */
    analytics.breadcrumb(
      "Opening selection for campus objects in stories preview"
    );
    this.setState({ searchCampusObject: true });
  };
  upload = () => {
    analytics.breadcrumb("Uploading stories");
    this.setState({ uploading: true });
    Campus.Funcs.stories
      .uploadStories(
        this.props.graphics,
        this.props.store.app.campus.key,
        this.props.store.society.manageSocietyFocus.id
      )
      .then(() => this.setState({ uploading: false, uploaded: true }))
      .catch((err) => {
        analytics.error(err, "CampusStories", "upload");
        this.setState({ uploadError: true, uploading: false });
      });
  };
}

const ANIMTOP = {
  SHOW: StaticSafeAreaInsets.safeAreaInsetsTop,
  HIDE: GlobalStyle.Measurements.height,
};

const styles = StyleSheet.create({
  container: {
    position: "absolute",

    width: GlobalStyle.Measurements.width,
    height: GlobalStyle.Measurements.height,
    paddingBottom: ANIMTOP.SHOW,

    backgroundColor: "#000",
    borderTopRightRadius: GlobalStyle.Measurements.unit,
    borderTopLeftRadius: GlobalStyle.Measurements.unit,

    shadowColor: "#000",
    shadowOffset: { width: 0, height: -5 },
    shadowOpacity: 0.4,
    shadowRadius: 10,
    elevation: 5,
  },
});
