import React from "react";
import { analytics } from "../../../assets/Analytics";
import { MAX_NUMBER_GRAPHICS, StoryCamera } from "./camera";
import { StoryPreview } from "./preview";

export class CampusStoriesMaker extends React.Component {
  /**
   * Parent class for stories.
   *
   * It handles the view and will return either the camera
   * or the preview depending if the user has composed
   * a story or not. If they have, then they will see the
   * preview
   */

  constructor() {
    super();
    this.state = {
      showPreview: false, // Whether to show the preview
      graphics: [], // Array of graphics
    };
    this.camera = React.createRef();
  }

  render() {
    return (
      <React.Fragment>
        <StoryCamera
          {...this.props}
          ref={this.camera}
          onGraphicsChange={this.handleGraphicsChange}
          showPreview={this.showPreview}
          showingPreview={this.state.showPreview}
        />
        <StoryPreview
          {...this.props}
          graphics={this.state.graphics}
          isActive={this.state.showPreview}
          onClose={this.handlePreviewClose}
          onGraphicDeleted={this.onGraphicDeleted}
        />
      </React.Fragment>
    );
  }
  handleGraphicsChange = (graphics) => {
    /** Handle a new or deleted graphic by updating the array in state */
    this.setState({ graphics });
    if (graphics.length >= MAX_NUMBER_GRAPHICS) this.showPreview();
  };
  showPreview = () => {
    analytics.breadcrumb("Showing stories preview");
    if (this.state.graphics.length >= 0) {
      this.setState({ showPreview: false }, () =>
        this.setState({ showPreview: true })
      );
    }
  };
  handlePreviewClose = ({ posted, error }) => {
    /**
     * Handle the closing of the preview.
     */
    analytics.breadcrumb("Closed stories preview");
    this.setState({ showPreview: false });
  };
  onGraphicDeleted = (index) => {
    // Update by calling the camera
    if (this.state.graphics.length == 1) this.setState({ showPreview: false });
    this.camera.current.onGraphicDeleted(index);
  };
}
