import React from "react";
import { TouchableOpacity, StyleSheet, Text, View } from "react-native";
import { GlobalStyle } from "../../../../assets/GlobalStyle";
import { analytics } from "../../../../assets/Analytics";
import Entypo from "react-native-vector-icons/Entypo";
import Ionicon from "react-native-vector-icons/Ionicons";
import { Linking } from "react-native";

export function HomeScreenFooterButtons(props) {
  const { campus } = props;
  return (
    <View style={styles.container.container}>
      {campus.campus_map_initial_coordinates && (
        <Component
          onPress={() =>
            props.navigate("Campus Map", {
              initialRegion: campus.campus_map_initial_coordinates,
            })
          }
          color={GlobalStyle.ColorStyle.blueButtonText}
          icon={"location-pin"}
          text={"Show campus map"}
        />
      )}
      {campus.security_number && (
        <Component
          onPress={() => {
            Linking.openURL(`tel:${campus.security_number}`);
            analytics.breadcrumb("User pressed security call button");
          }}
          color={"#ed4c4c"}
          icon={"phone"}
          text={"Call security (24/7)"}
        />
      )}
    </View>
  );
}

function Component({ color, onPress, icon, text }) {
  return (
    <TouchableOpacity onPress={onPress} style={styles.component.container}>
      <View
        style={[styles.component.leftIcon, { backgroundColor: `${color}20` }]}
      >
        <Entypo
          name={icon}
          color={color}
          size={GlobalStyle.Measurements.unit * 0.9}
        />
      </View>
      <Text style={[GlobalStyle.ButtonStyle.TextButton, { color }]}>
        {text}
      </Text>
      <View style={styles.component.rightIcon}>
        <Ionicon
          name={"arrow-forward"}
          color={color}
          size={GlobalStyle.Measurements.unit * 0.8}
        />
      </View>
    </TouchableOpacity>
  );
}

const styles = {
  container: StyleSheet.create({
    container: {
      marginVertical: GlobalStyle.Measurements.margin,
      alignSelf: "center",
      alignItems: "center",
      justifyContent: "center",
    },
  }),
  component: StyleSheet.create({
    container: {
      width: GlobalStyle.Measurements.width * 0.8,
      flexDirection: "row",
      alignItems: "center",
      justifyContent: "flex-start",
      alignSelf: "center",
      marginVertical: GlobalStyle.Measurements.marginHalf,
    },
    leftIcon: {
      alignItems: "center",
      justifyContent: "center",
      borderRadius: 100,
      padding: 8,
      marginRight: GlobalStyle.Measurements.margin,
    },
    rightIcon: {
      alignItems: "center",
      justifyContent: "center",
      marginLeft: 5,
    },
  }),
};

const mapPadding = {
  bottom: -30,
  top: -30,
};
