import React from "react";
import { StyleSheet, Pressable, Animated } from "react-native";
import { GlobalStyle } from "../../../../assets/GlobalStyle";
import * as Animtable from "react-native-animatable";
import { AnimatedCircularProgress } from "react-native-circular-progress";
import { Easing } from "react-native";
import { styles as storyStyles } from "../style";

export const MAX_VIDEO_DURATION = 8000; // Mlliseconds

const AnimPressable = Animtable.createAnimatableComponent(Pressable);

export class CaptureButton extends React.Component {
  /**
   * Capture button to visualize and capture images and videos
   *
   * INFORMATION: When an animation in circular is done, a new key will be set to reset
   * the animation circle to zero without animation
   */
  constructor() {
    super();
    this.state = {
      holding: false,
      fill: 0,
      key: "1",
    };

    this.pressable = React.createRef();
    this.circular = React.createRef();
    this.timeout;
  }

  componentDidUpdate(prevProps) {
    const { maxGraphicsReached: prevMaxGraphicsReached } = prevProps;
    const { maxGraphicsReached } = this.props;

    if (this.pressable.current) {
      const pressable = this.pressable.current;
      const duration = 500;
      if (maxGraphicsReached && !prevMaxGraphicsReached)
        pressable.fadeOut(duration);
      else if (!maxGraphicsReached && prevMaxGraphicsReached)
        pressable.fadeIn(duration);
    }
  }

  render() {
    return (
      <AnimPressable
        ref={this.pressable}
        style={[storyStyles.iconShadow, styles.container]}
        hitSlop={10}
        onPress={this.onPress}
        onTouchEnd={this.onPressEnd}
        onLongPress={this.onLongPress}
      >
        {this.state.holding && (
          <Animtable.View
            ref={this.circular}
            style={styles.circular}
            animation={CIRCULAR_ANIMATION}
            iterationCount={"infinite"}
            duration={850}
            iterationDelay={1300}
          >
            <AnimatedCircularProgress
              key={this.state.key}
              padding={3}
              width={5}
              lineCap={"round"}
              duration={MAX_VIDEO_DURATION}
              fill={this.state.fill}
              rotation={360}
              easing={Easing.linear}
              size={CAPTURE_SIZE - 2}
              tintColor={this.props.colors.main}
              onAnimationComplete={this.onMaxDurationReached}
            />
          </Animtable.View>
        )}
      </AnimPressable>
    );
  }

  onLongPress = () => {
    this.setState({ holding: true, fill: 100 });
    this.scaleButton(1.2);
    this.props.startRecording();
  };
  onPressEnd = () => {
    // TODO: How to zoom the video or image
    this.setState({ holding: false, fill: 0 });
    this.scaleButton(1);
    this.incrementKey();
    this.props.stopRecording();
  };
  onPress = () => {
    this.props.takePicture();
  };

  incrementKey = () => {
    /** Used to reset the circular to zero without animation
     *  by creating a new component when setting a different key
     */
    this.setState({ key: parseInt(this.state.key) + 1 });
  };

  onMaxDurationReached = () => {
    if (this.state.holding && this.state.fill > 95) {
      this.incrementKey();
      this.props.restartRecording();
    }
  };

  scaleButton = (value = 1) => {
    this.pressable.current.transitionTo({ scale: value }, 500);
    try {
      this.circular.current.transitionTo({ scale: value * 1.2 }, 500);
    } catch {}
  };
}

export const CAPTURE_SIZE = GlobalStyle.Measurements.width * 0.185;
export const styles = StyleSheet.create({
  container: {
    width: CAPTURE_SIZE,
    height: CAPTURE_SIZE,
    borderRadius: CAPTURE_SIZE / 2,

    backgroundColor: GlobalStyle.Palettes.background.palette6,
    opacity: 1,

    position: "absolute",
    alignSelf: "center",

    marginTop: GlobalStyle.Measurements.height * 0.95 - CAPTURE_SIZE,
  },
  circular: {
    width: CAPTURE_SIZE,
    height: CAPTURE_SIZE,
  },
});

const CIRCULAR_ANIMATION = {
  0: { opacity: 1 },
  0.5: { opacity: 0.4 },
  1: { opacity: 1 },
};
