import React from "react";
import { StyleSheet } from "react-native";
import { View, Text, TouchableOpacity } from "react-native";
import StaticSafeAreaInsets from "react-native-static-safe-area-insets";
import FontAwesome5Icon from "react-native-vector-icons/FontAwesome5";
import { GlobalStyle } from "../../../../assets/GlobalStyle";

export function PreviewHeader(props) {
  const { updateSettings, settings } = props;

  function updateMuted() {
    const currentValue = settings.muted;
    updateSettings("muted", !currentValue);
  }
  function updateRepeat() {
    const currentValue = settings.repeat;
    updateSettings("repeat", !currentValue);
  }

  return (
    <View style={styles.container}>
      <Icon icon={"chevron-down"} noMargin onPress={props.close} />

      <View style={styles.toolbarRow}>
        <Icon icon={"calendar-plus"} onPress={props.selectCampusObject} />
        <Icon
          icon={"sync"}
          onPress={updateRepeat}
          off={!settings.repeat}
          scale={0.9}
        />
        <Icon
          icon={settings.muted ? "volume-mute" : "volume-up"}
          onPress={updateMuted}
        />
      </View>
    </View>
  );
}

function Icon(props) {
  const toolbarMargin = GlobalStyle.Measurements.width / 2 / 12;
  return (
    <TouchableOpacity
      style={[styles.icon, !props.noMargin && { marginLeft: toolbarMargin }]}
      onPress={props.onPress}
    >
      <FontAwesome5Icon
        name={props.icon}
        color={"#fff"}
        size={GlobalStyle.Measurements.unit * (props.scale || 1)}
      />
      {props.off && <View style={styles.slash} />}
    </TouchableOpacity>
  );
}
const ICON_SIZE = GlobalStyle.Measurements.unit;
const ICON_PADDING = 5;

const styles = StyleSheet.create({
  container: {
    position: "absolute",

    width: GlobalStyle.Measurements.width,
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    padding: GlobalStyle.Measurements.margin,
  },
  text: {},
  icon: {
    width: ICON_SIZE + ICON_PADDING,
    height: ICON_SIZE + ICON_PADDING,
    alignItems: "center",
    justifyContent: "center",
  },
  toolbarRow: {
    flexDirection: "row",
    justifyContent: "flex-end",
    alignItems: "center",
  },
  slash: {
    width: 2,
    height: ICON_SIZE + ICON_PADDING * 2,
    backgroundColor: "#fff",
    alignSelf: "center",
    position: "absolute",
    transform: [{ rotate: "-45deg" }],
  },
});
