import React from "react";
import { StyleSheet } from "react-native";
import { Pressable } from "react-native";
import Ionicon from "react-native-vector-icons/Ionicons";
import { GlobalStyle } from "../../../../assets/GlobalStyle";
import { CAPTURE_SIZE, styles as captureStyles } from "./CaptureButton";
import { styles as storyStyles } from "../style";
import { createAnimatableComponent } from "react-native-animatable";
const AnimPressable = createAnimatableComponent(Pressable);

export class FlipCamera extends React.Component {
  constructor() {
    super();
    this.pressable = React.createRef();
  }
  componentDidUpdate(prevProps) {
    const { maxGraphicsReached: prevMaxGraphicsReached } = prevProps;
    const { maxGraphicsReached } = this.props;

    if (this.pressable.current) {
      const pressable = this.pressable.current;
      const duration = 500;
      if (maxGraphicsReached && !prevMaxGraphicsReached)
        pressable.fadeOut(duration);
      else if (!maxGraphicsReached && prevMaxGraphicsReached)
        pressable.fadeIn(duration);
    }
  }

  render() {
    return (
      <AnimPressable
        ref={this.pressable}
        style={[storyStyles.iconShadow, styles.container]}
        onTouchStart={this.props.onPress}
      >
        <Ionicon name={"repeat"} color={"#fff"} size={SIZE} />
      </AnimPressable>
    );
  }
}
const SIZE = GlobalStyle.Measurements.width * 0.075;
const styles = StyleSheet.create({
  container: {
    position: "absolute",

    marginTop: captureStyles.container.marginTop - CAPTURE_SIZE,
    alignSelf: "center",
  },
});
